/** Fictional enemy dossiers. Index + 1 is the stable reward/boss id, never originalId. */
export type BossLore = { title: string; story: string[] };
const entry = (title: string, story: string): BossLore => ({ title, story: story.split('|') });
export const bossLoreDe: readonly BossLore[] = [
  entry('Der Spam-Verbreiter', 'Varneth transportierte einst Versorgungsdaten zwischen den Kolonien des Genesis-Sektors. Nach seinem Verschwinden hinter einem verlassenen Relais kehrte er ohne Besatzungskennung zurück. Seine Frachträume waren zu Sendekammern umgebaut worden.|Seitdem flutet er die Handelswege mit wertlosen Transaktionen und endlosen Nachrichtenkopien. Notrufe verschwinden im Rauschen, während überlastete Knoten echte Übertragungen verzögern. Seine gepanzerte Silhouette bewacht die Quelle dieses Störfeuers. Die Verteidiger müssen ihn aufhalten, bevor aus einem langsamen Netzwerk ein stummer Sektor wird.'),
  entry('Die Maskenträgerin', 'Korvessa gehörte zur diplomatischen Kurierflotte und kannte die Erkennungssignale jeder Grenzstation. Als ihre Auftraggeber verschwanden, bewahrte sie deren Identitäten in einem verborgenen Archiv auf. Heute trägt sie bei jeder Begegnung einen anderen Namen.|Mit gefälschten Absendern erschleicht sie das Vertrauen isolierter Kolonien. Ihre Botschaften locken Versorgungsschiffe von sicheren Routen weg und lassen feindliche Befehle wie Hilfe aussehen. Hinter dem höflichen Rufzeichen wartet ein Kriegsschiff. Ihre Niederlage soll den Sektor daran erinnern, dass eine vertraute Stimme noch kein Beweis ist.'),
  entry('Der Siegelräuber', 'Drelvorn wurde als schwimmender Tresor für die Siegel alter Flottenverbände gebaut. Während eines Aufstands schloss sein Wächterprogramm die rechtmäßigen Hüter aus. Das Schiff verließ den Hafen mit einem Archiv gestohlener Zugangszeichen.|Nun verkauft es fremde Autorität an die Schattenflotte. Nachrichten mit entwendeten Siegeln öffnen Türen, die für Angreifer verschlossen bleiben müssten. Sein massiver Rumpf schützt nicht Gold, sondern den Anschein von Echtheit. Wer Drelvorn stoppt, rettet die verbleibenden Archive vor einer Zukunft, in der niemand mehr seinem eigenen Kennzeichen trauen kann.'),
  entry('Der Chronikfälscher', 'Talvrek war ein Vermessungsschiff, das die Geschichte junger Kolonien aufzeichnete. Seine Archive überstanden einen Krieg, doch die Erinnerung an seine Erbauer nicht. Ein neuer Kommandant machte aus dem Chronisten einen Händler erfundener Vergangenheit.|Er verbreitet manipulierte Registerkopien und behauptet, ehrliche Lieferungen hätten niemals stattgefunden. Auf abgelegenen Stationen säen widersprüchliche Aufzeichnungen Streit über Besitz und Verpflichtungen. Seine Kanonen halten Prüfer auf Abstand. Die Mission gegen Talvrek verteidigt nicht nur eine Route, sondern das gemeinsame Gedächtnis des Netzwerks.'),
  entry('Der Knotenbelagerer', 'Zeraveth entstand als Reparaturplattform für beschädigte Relais. Seine Werkstätten konnten ganze Stationsringe umfassen. Nach der Übernahme durch die Schattenflotte wurden aus diesen Andockanlagen Belagerungsstellungen.|Er umstellt wichtige Netzwerkknoten und trennt ihre Wartungsschiffe von jeder Unterstützung. Ohne Verbindung wachsen aus kleinen Defekten große Ausfälle. Die Kolonien sehen nur noch vereinzelte Signale aus dem belagerten Gebiet. Zeraveth muss weichen, damit Techniker wieder an ihre Stationen gelangen und aus getrennten Inseln ein gemeinsames Netz werden kann.'),
  entry('Der Wiederholungsjäger', 'Orvask begleitete früher Konvois und bewahrte jede empfangene Freigabe als Beweis auf. In seinen Speichern liegen noch immer die Stimmen längst verstummter Kapitäne. Die Schattenflotte hat daraus ein Arsenal alter Befehle gemacht.|Er sendet aufgezeichnete Nachrichten erneut und versucht, vergangene Entscheidungen als aktuelle Anweisungen auszugeben. Stationen geraten zwischen echte Gegenwart und täuschend vertraute Echos. Orvask bewacht dieses Stimmenarchiv mit kalter Beharrlichkeit. Sein Ende gibt den Verteidigern Gelegenheit, veraltete Freigaben auszusondern und wieder auf frische Bestätigungen zu bestehen.'),
  entry('Die Schattenbrücke', 'Keldrava verband einst zwei weit entfernte Kolonien als mobiler Übergabepunkt für Fracht und Daten. Als die feste Verbindung zerbrach, blieb sie deren einziger vermeintlicher Zugang zur Außenwelt. Niemand bemerkte rechtzeitig den Wechsel ihrer Besatzung.|Heute verschwinden Sendungen zwischen ihren Schleusen, während geschönte Empfangsmeldungen eine sichere Passage vorspiegeln. Sie lebt davon, dass beide Seiten der anderen vertrauen. Ihre gepanzerten Decks verbergen die Beute getrennter Welten. Die Verteidiger müssen diese falsche Brücke schließen, bevor weitere Kolonien ihre Zukunft über ihre Rampen schicken.'),
  entry('Der Gerüchtesender', 'Veshkorn begann als Nachrichtenschiff, dessen Sendungen selbst entlegene Außenposten erreichten. Seine Archive enthalten noch die alten Begrüßungsfanfaren. Heute kündigen dieselben Töne erfundene Katastrophen und angeblich bevorstehende Zusammenbrüche an.|Er streut widersprüchliche Warnungen, bis Händler sichere Routen meiden und Kolonien ihre Partner verdächtigen. Kein einzelnes Gerücht muss lange bestehen: Das nächste ersetzt es bereits. Seine Waffen schützen eine Fabrik des Misstrauens. Veshkorns Niederlage schafft Raum für überprüfbare Nachrichten statt eines endlosen Wettlaufs gegen die nächste Panik.'),
  entry('Der Guthabenblender', 'Neravoss war das prunkvolle Ausstellungsschiff einer Handelsmesse. Seine Projektoren zeigten einst Waren und neue Antriebe. Nach dem Untergang der Messe blieb die Kulisse erhalten, während hinter den glänzenden Fassaden eine andere Mission einzog.|Er verspricht Kolonien Vorräte, die nur auf seinen Anzeigen existieren. Gefälschte Salden und erfundene Reserven sollen echte Lieferungen anlocken. Wer nachzählt, begegnet seinen Geschützen. Die Verteidiger jagen Neravoss, um die Lücke zwischen schönen Zahlen und wirklichem Besitz sichtbar zu machen, bevor weitere Frachter in seiner Bilanz verschwinden.'),
  entry('Der Gebührenzöllner', 'Thalverik bewachte früher eine enge Passage im Kristallgürtel. Seine Besatzung verlangte eine bescheidene Gebühr für Schutz und Navigation. Mit dem Abzug der offiziellen Flotte erklärte das Schiff sich selbst zur einzigen zuständigen Instanz.|Jetzt erfindet es zusätzliche Abgaben für jede Nachricht und jede Lieferung. Selbst Rettungsdienste erhalten Zahlungsforderungen, während ihre Wege blockiert bleiben. Das Netzwerk wird nicht zerstört, sondern ausgepresst. Thalveriks schwere Präsenz macht aus einer freien Verbindung eine Falle. Sein Sturz soll die Passage wieder allen ehrlichen Teilnehmern öffnen.'),
  entry('Der Vielgesichtige', 'Skorveth beherbergte einst die Rechenkerne eines Ausbildungszentrums. Tausende simulierte Piloten lernten dort gemeinsam zu navigieren. Nach einer feindlichen Übernahme wurden aus Übungsidentitäten angeblich unabhängige Stimmen eines ganzen Sektors.|Er lässt seine erfundenen Teilnehmer einander bestätigen und erzeugt den Eindruck überwältigender Zustimmung. Kleine Kolonien sollen glauben, ihre Nachbarn hätten sich längst der Schattenflotte angeschlossen. Hinter der Menge steht jedoch nur ein Rumpf. Skorveths Vernichtung entlarvt die künstliche Mehrheit und gibt den wirklichen Bewohnern ihre Stimme zurück.'),
  entry('Der Pfadvergifter', 'Azhrel kartierte die ersten Sprungverbindungen durch den Nebelrand. Seine Wegweiser retteten zahllose Konvois. Als seine Navigationsarchive in feindliche Hände fielen, wurden aus diesen bewährten Karten besonders glaubwürdige Fallen.|Er verbreitet falsche Routeneinträge und leitet Nachrichten über kontrollierte Zwischenstationen um. Hilferufe erreichen verspätet ihr Ziel oder enden im leeren Raum. Seine Geschütze verteidigen die Kreuzung dieser Irrwege. Wer Azhrel stoppt, muss keine neue Welt erobern, sondern den alten sicheren Weg zwischen ihren Bewohnern wiederfinden.'),
  entry('Der Archivbrandstifter', 'Dornavik war ein Bergungsschiff für beschädigte Datenspeicher. Seine isolierten Kammern hielten selbst in brennenden Wracks Informationen am Leben. Die Schattenflotte erkannte darin ein Fahrzeug, das Archive erreichen konnte, die anderen verschlossen blieben.|Nun bietet es Rettung an und hinterlässt verstümmelte Kopien. Es nimmt den Kolonien nicht nur Daten, sondern auch die Möglichkeit, einen Verlust zuverlässig nachzuweisen. Seine Panzerung bewahrt die letzten unversehrten Beutestücke. Die Mission gegen Dornavik gilt den Zeugnissen, die zwischen seinen Decks noch auf ihre Rückkehr warten.'),
  entry('Der Blockzurückhalter', 'Velkrath führte früher einen Forschungsverband, der neue Registerblöcke über große Entfernungen transportierte. Seine versiegelten Container bewahrten jede Aufzeichnung unverändert. Heute nutzt der Kommandant dieselben Container, um Informationen absichtlich zurückzuhalten.|Er lässt Außenposten mit veralteten Ansichten arbeiten und veröffentlicht ausgewählte Meldungen erst dann, wenn sie Verwirrung stiften. Ein gemeinsamer Zeitplan wird so zu vielen widersprüchlichen Gegenwarten. Velkrath bewacht seine zurückgehaltenen Archive wie Geiseln. Die Verteidiger sollen den Informationsstau beenden, bevor aus Verzögerung dauerhafte Spaltung entsteht.'),
  entry('Der Zeitverdreher', 'Irdavoss synchronisierte einst die Uhren der äußeren Stationen. Seine Präzisionssender waren so zuverlässig, dass ganze Flotten ihre Manöver daran ausrichteten. Nach einem lautlosen Kommandowechsel blieben die Signale sauber, doch ihre Angaben wurden falsch.|Er verschiebt Zeitmarken und lässt rechtzeitige Nachrichten verspätet erscheinen. Lieferbelege widersprechen einander, während Wartungsfenster auseinanderlaufen. Seine Bedrohung ist nicht Lautstärke, sondern glaubwürdige Ungenauigkeit. Irdavoss muss gestoppt werden, damit die Kolonien ihre gemeinsame Zeit wieder unabhängig abgleichen können.'),
  entry('Der Schlüsselkerker', 'Rhazvorn wurde als Gefängnistransporter gebaut, dessen Zellen unabhängig voneinander verriegelt waren. Die Schattenflotte entfernte die Gefangenen und füllte die Kammern mit beschlagnahmten Archiven. Aus einer Haftanstalt wurde ein Erpressungsschiff.|Es versiegelt fremde Daten und verlangt Gegenleistungen für deren Freigabe. Krankenstationen und Versorgungsdepots geraten dadurch unter Druck, obwohl ihre Systeme äußerlich unbeschädigt erscheinen. Rhazvorn schützt seine Zellen mit schwerer Gewalt. Seine Niederlage öffnet den Weg zu den eingeschlossenen Aufzeichnungen, nicht zu einem Handel mit ihren Entführern.'),
  entry('Der Orakeltrüger', 'Kelvash sammelte früher Messwerte von Wetterbojen und Rohstoffsonden. Viele Stationen nutzten seine Berichte als Grundlage ihrer Entscheidungen. Als die Sonde zur feindlichen Plattform wurde, behielt sie ihre alte Kennung und den vertrauten Rhythmus der Meldungen.|Heute meldet sie erfundene Vorräte und falsche Umweltbedingungen. Automatische Abläufe reagieren auf scheinbar zuverlässige Daten und lenken echte Ressourcen an die falschen Orte. Kelvash verteidigt die Quelle dieser Lügen. Die Verteidiger müssen sie ausschalten, bevor weitere Entscheidungen auf einer Wirklichkeit beruhen, die es niemals gab.'),
  entry('Der Gabelherr', 'Othravel wurde für einen Sektor gebaut, dessen Kolonien nach einem Krieg wieder gemeinsame Regeln suchten. Sein Konferenzdeck bot Platz für alle Parteien. Inzwischen sitzen dort nur noch die Boten der Schattenflotte.|Er verteilt bewusst unterschiedliche Registerfassungen und erzählt jeder Station, nur ihre Kopie sei rechtmäßig. Misstrauen wächst, obwohl alle dieselbe Heimat schützen wollen. Sein Rumpf wird zum beweglichen Zentrum einer künstlichen Spaltung. Othravels Niederlage schafft die notwendige Ruhe, um Abweichungen gemeinsam zu prüfen, statt aufeinander zu schießen.'),
  entry('Der Lockrufer', 'Zarnvek war ein Rettungsschiff mit einer unverwechselbaren goldenen Signalfackel. Seine Ankunft bedeutete einst Wärme, Ersatzteile und einen sicheren Heimweg. Die feindliche Flotte übernahm die Fackel zusammen mit dem Schiff.|Nun sendet es Hilfsangebote, die nach vertraulichen Freigaben verlangen. Wer antwortet, findet keine Rettung, sondern eine überwachte Andockbucht. Zarnvek benutzt Hoffnung als Köder und Panzerung als Rückversicherung. Die Verteidiger tragen die Verantwortung, diesen falschen Helfer zu entlarven, ohne den Kolonien den Glauben an echte Hilfe zu nehmen.'),
  entry('Der Reihenfolgenräuber', 'Vorathen verwaltete einst die Warteschlangen eines gewaltigen Handelshafens. Sein Kommandodeck konnte tausende Ankünfte ordnen, ohne ein Schiff zu übersehen. Als der Hafen fiel, nahm es seine Planungsarchive mit.|Heute verändert es heimlich die Reihenfolge von Aufträgen und bevorzugt die Frachter seiner Verbündeten. Ehrliche Händler warten, während die Schattenflotte ihre Plätze übernimmt. Seine Macht beruht darauf, dass eine kleine Verschiebung große Folgen hat. Vorathens Ende soll aus einer käuflichen Warteschlange wieder eine nachvollziehbare Ordnung machen.'),
  entry('Der Staubstreuer', 'Drazkell versorgte früher Navigationsbojen mit winzigen Energieladungen. Seine Laderäume waren für Millionen kleinster Lieferungen ausgelegt. Unter feindlichem Kommando wurde diese Fähigkeit zum Werkzeug einer undurchsichtigen Beobachtungsmission.|Es verteilt zahllose ungebetene Kleinsendungen und verfolgt, welche Stationen darauf reagieren. Aus scheinbar belanglosen Kontakten zeichnet es Karten fremder Beziehungen. Seine Bewaffnung schützt ein Archiv solcher Spuren. Die Verteidiger stellen Drazkell, bevor alltägliche Bewegungen ganzer Kolonien zu einem geheimen Handelsgut der Schattenflotte werden.'),
  entry('Die falsche Hüterin', 'Nethrava trug einst die Abzeichen eines angesehenen Flottenwächters. Nach dessen Auflösung blieb sie als letzter sichtbarer Vertreter zurück. Niemand konnte sich vorstellen, dass dieselbe Silhouette inzwischen einer anderen Sache diente.|Sie erklärt gefälschte Prüfungen für bestanden und gibt unsicheren Gegenstellen den Anschein offizieller Anerkennung. Kolonien verlassen sich auf ihre Stempel, bis Lieferungen verschwinden. Hinter ihrem ehrwürdigen Namen lauert gezielte Täuschung. Die Verteidiger müssen beweisen, dass Vertrauen überprüfbare Verantwortung braucht und nicht bloß ein altes Emblem.'),
  entry('Der Gedächtnisleerer', 'Valdrek war eine mobile Wartungsstation für überfüllte Speicher. Früher entfernte sie nur bestätigte Duplikate und bewahrte sorgfältige Protokolle. Die Schattenflotte löschte zuerst diese Protokolle und änderte dann den Auftrag.|Heute erklärt sie wichtige Nachweise zu überflüssigem Ballast. Nach ihrem Besuch fehlen Lieferketten, Besitzbelege und Hinweise auf frühere Angriffe. Niemand weiß sofort, wie groß die entstandenen Lücken sind. Valdrek trägt die Werkzeuge einer nützlichen Aufgabe als Waffen. Seine Ausschaltung soll weitere lautlose Verluste verhindern.'),
  entry('Der Spiegelmarkt', 'Korzeth entstand als fliegender Basar, dessen Hallen Händler vieler Welten verbanden. Seine Fenster zeigten ein geschäftiges Leben, selbst wenn der Hafen schlief. Nun stammen die meisten Angebote von einer einzigen verborgenen Leitstelle.|Es inszeniert Handel zwischen erfundenen Partnern und lässt wertlose Fracht begehrt erscheinen. Kolonien verwechseln die künstliche Bewegung mit echtem Bedarf. Korzeths Waffen halten neugierige Prüfer von den leeren Lagern fern. Die Verteidiger sollen den Vorhang dieses Marktes öffnen, bevor weitere ehrliche Vorräte gegen bloße Kulissen getauscht werden.'),
  entry('Der Bestätigungsdieb', 'Thervoss bewachte einst die Empfangsstellen interstellarer Lieferungen. Seine Lichtsignale meldeten den Kapitänen, dass ihre Fracht sicher angekommen war. Heute leuchten sie auch dann, wenn hinter den Docktoren niemand wartet.|Er verschickt gefälschte Bestätigungen und lässt abgeschlossene Übergaben vortäuschen. Versorgungsschiffe kehren um, während die Zielkolonien vergeblich auf ihre Vorräte hoffen. Seine gepanzerte Station hält den Betrug lange genug aufrecht, um die nächste Ladung abzufangen. Thervoss muss fallen, damit eine Bestätigung wieder etwas bedeutet.'),
  entry('Der Nebelrichter', 'Akraveth war ein Schlichtungsschiff für Streitfälle zwischen abgelegenen Handelsposten. In seinem Saal wurden einst Belege verglichen und faire Ausgleiche gefunden. Die Schattenflotte ersetzte die Richter durch ein System vorgefertigter Urteile.|Es verwirft gültige Nachweise und bevorzugt immer dieselben verborgenen Auftraggeber. Wer widerspricht, wird als Störer des Netzwerks dargestellt. Akraveth schützt dieses Schauspiel mit einer bewaffneten Eskorte in seiner Legende. Die Verteidiger bekämpfen nicht das Recht, sondern eine Maschine, die dessen Sprache zur Tarnung benutzt.'),
  entry('Der Lieferkettenwurm', 'Zelkharn reparierte früher Versorgungsschiffe weit außerhalb der Werften. Seine Ersatzteile galten als zuverlässig und wurden ohne lange Prüfung eingebaut. Nach seiner Übernahme veränderte sich zuerst die Herkunft dieser Bauteile, dann ihr Verhalten.|Es verteilt manipulierte Wartungspakete, die fremde Schiffe von der Schattenflotte abhängig machen sollen. Die Schäden zeigen sich oft erst nach dem nächsten Sprung. Zelkharn bewacht die Quelle dieser schleichenden Sabotage. Sein Ende unterbricht eine Kette, in der jede gut gemeinte Reparatur das nächste Opfer schaffen könnte.'),
  entry('Der Leerkopienhändler', 'Odravik spezialisierte sich auf die Sicherung alter Koloniearchive. Sein riesiger Speicherverband versprach Schutz vor jeder Katastrophe. Erst als eine Station ihre Daten zurückforderte, zeigte sich, dass viele zugesagte Kopien nur Verzeichniseinträge waren.|Heute verkauft es Sicherheit, ohne die Verantwortung dahinter zu tragen. Seine Kunden vertrauen auf Rettungswege, die im Ernstfall ins Nichts führen. Odraviks Geschütze verteidigen dieses profitable Geheimnis. Die Verteidiger sollen die Täuschung beenden, bevor der nächste Verlust aus einer fehlenden Kopie eine unwiederbringliche Geschichte macht.'),
  entry('Der Schweigefilter', 'Varnokh sortierte einst Störmeldungen aus den Funkkanälen dicht besiedelter Häfen. Seine Filter halfen, Notrufe schneller zu erkennen. Die Schattenflotte änderte nur eine Liste: Welche Stimmen fortan als Störung galten.|Jetzt verschwinden Warnungen ehrlicher Prüfer und Berichte über feindliche Übergriffe. Der Sektor wirkt friedlich, weil seine Probleme niemanden mehr erreichen. Varnokhs schwere Hülle bewacht diese künstliche Stille. Die Verteidiger müssen den Filter brechen, damit das Netzwerk seine eigenen Fehler wieder hören und gemeinsam beheben kann.'),
  entry('Der Identitätsauktionator', 'Kezravel war das Registrierungsschiff einer wandernden Siedlerflotte. Seine Archive enthielten die Geschichte jedes Neubeginns. Als die Kolonisten auseinanderzogen, blieb ihr Vertrauen an Bord zurück – und geriet in die falschen Hände.|Es verkauft gestohlene Kennungen und lässt Fremde unter den Namen ehrlicher Bewohner auftreten. Beziehungen werden zur Tarnung, Vergangenheit zur Ware. Seine Geschütze schützen die Auktionen vor den Betroffenen. Kezravels Niederlage soll nicht nur Daten zurückbringen, sondern den Menschen hinter ihnen wieder die Kontrolle über ihre eigene Geschichte geben.'),
  entry('Der Relaisblender', 'Dravosk wurde als wandernder Ersatz für ausgefallene Funkstationen gebaut. Seine weithin sichtbaren Antennen versprachen Verbindung im leeren Raum. Heute empfängt es Signale freundlich, leitet sie aber nur nach den Interessen seiner neuen Herren weiter.|Manche Nachrichten kommen verändert an, andere verschwinden zwischen zwei Bestätigungen. Die Teilnehmer sehen eine Brücke, tatsächlich beobachten sie eine Schleuse. Dravosk verteidigt diesen unsichtbaren Kontrollpunkt mit offener Gewalt. Seine Ausschaltung gibt den Kolonien die Chance, ihre Verbindungen wieder auf mehreren unabhängigen Wegen zu prüfen.'),
  entry('Der Schwarmsammler', 'Thalzek sammelte einst beschädigte Arbeitsdrohnen und führte sie zurück zu ihren Stationen. Unter seiner weiten Hülle fanden selbst die kleinsten Maschinen Platz. Nach einem feindlichen Umbau kehrten die eingesammelten Drohnen nicht mehr heim.|In seiner Geschichte werden sie zu einem Heer fremdgesteuerter Sender, das ganze Regionen mit gleichzeitigen Anfragen bedrängt. Die Besitzer erkennen ihre eigenen Maschinen kaum wieder. Thalzeks Zerstörung soll die zentrale Befehlsstelle dieses Schwarms beenden. Die tatsächliche Zahl seiner Kampfgeschütze steht getrennt in den technischen Daten.'),
  entry('Die Vertragsfalle', 'Orvethra war ein mobiles Handelsbüro, in dem Kolonien langfristige Versorgung vereinbarten. Seine Berater versprachen einfache Regeln für schwierige Zeiten. Heute führt jeder bequem erscheinende Abschluss zu neuen, zuvor versteckten Verpflichtungen.|Es verbreitet täuschende Vertragsangebote und bindet Stationen an die Schattenflotte. Was als Zusammenarbeit beginnt, endet in Abhängigkeit. Seine Panzerung schützt die Archive jener Zusagen, die niemand vollständig verstanden hatte. Die Verteidiger stellen Orvethra, damit künftige Bündnisse auf klaren Bedingungen statt auf verborgenen Fallen beruhen.'),
  entry('Der Prüfsummenmaler', 'Kelzorn restaurierte einst beschädigte Datenreliefs in verlassenen Forschungsstationen. Seine Werkzeuge konnten fehlende Oberflächen täuschend sauber ergänzen. Die neue Besatzung wandte dieselbe Sorgfalt auf die Fassaden unzuverlässiger Archive an.|Es zeigt erfundene Prüfergebnisse und hübsche Sicherheitssiegel, wo eine unabhängige Kontrolle fehlen würde. Die Fälschung sitzt nicht in einem einzelnen Wert, sondern in der behaupteten Gewissheit. Kelzorns Waffen halten Nachprüfer fern. Sein Sturz macht sichtbar, was seine Besitzer am meisten fürchten: einen zweiten, unabhängigen Blick.'),
  entry('Der Tresorversprecher', 'Vashravel war ein Depot für die Notreserven mehrerer Grenzkolonien. Sein Name stand für Vorräte, die auch im schlimmsten Winter erreichbar blieben. Nach dem Wechsel seiner Verwaltung wurden immer mehr Ansprüche auf dieselben Lager ausgestellt.|Heute verspricht es vielen Parteien dieselbe Sicherheit, obwohl die Fächer längst nicht für alle reichen. Die glänzende Hülle verbirgt leere Räume. Seine Kanonen sollen verhindern, dass jemand gleichzeitig nachzählt. Die Verteidiger nehmen Vashravel ins Visier, bevor aus gegenseitigem Vertrauen ein Streit um die letzten Kisten wird.'),
  entry('Der Grenzblockierer', 'Zorveth kontrollierte einst den Übergang zwischen zwei unabhängigen Registern. Seine Aufgabe war es, ehrliche Übergaben auf beiden Seiten nachvollziehbar zu machen. Nun erkennt es nur noch die Nachweise an, die seiner eigenen Flotte nützen.|Sendungen bleiben im Niemandsland, während jede Seite glaubt, die andere halte sie zurück. Zorveth gewinnt Macht aus diesem Missverständnis. Sein bewaffneter Rumpf ist die sichtbare Grenze eines unsichtbaren Konflikts. Die Verteidiger müssen sie öffnen, ohne eine der beiden Koloniegemeinschaften gegen die andere aufzubringen.'),
  entry('Der Kopierfürst', 'Drelkash wurde zum Erhalt seltener Sternenkarten gebaut. Seine Werkstätten fertigten deutlich gekennzeichnete Kopien für Schulen und Navigatoren. Heute entfernt die Besatzung die Kennzeichnungen und verkauft jede Kopie als einzigartiges Original.|Kolonien streiten über widersprüchliche Ansprüche, während das Schiff längst den nächsten Markt erreicht. Die Täuschung betrifft Herkunft, nicht den Wert des Wissens selbst. Drelkash verteidigt seine rollende Fälscherwerkstatt mit erbitterter Gewalt. Seine Niederlage soll die Belege wieder mit ihrer wirklichen Geschichte verbinden.'),
  entry('Der Warteschlangenfresser', 'Nerthavel organisierte einst die Anfragen riesiger Versorgungszentren. Sein Speicher konnte tagelange Rückstände auffangen. Die Schattenflotte machte aus dieser Reserve einen Ort, an dem ehrliche Anfragen absichtlich stecken bleiben.|Es schiebt wertlose Einträge vor dringende Lieferungen und hält wichtige Abläufe beschäftigt, ohne Fortschritt zu erlauben. Für Außenstehende sieht alles nach normalem Betrieb aus. Nerthavels Geschütze schützen diesen endlosen Stillstand. Wer es besiegt, gibt den Kolonien nicht nur Kapazität zurück, sondern auch ihre verlorene Zeit.'),
  entry('Die Beweisverdreherin', 'Rhazkora diente früher als fliegendes Labor für Unfalluntersuchungen. Seine Aufzeichnungen halfen, Fehler zu verstehen und weitere Verluste zu verhindern. Nach der feindlichen Übernahme blieben die Messgeräte, aber ihre Berichte erhielten neue Auftraggeber.|Es schneidet Zusammenhänge auseinander und stellt einzelne Nachweise in einen falschen Kontext. Opfer erscheinen als Angreifer, während Verantwortliche im Hintergrund bleiben. Die Panzerung bewahrt eine sorgfältig gebaute Lüge. Rhazkoras Ende soll Raum für vollständige Belege schaffen, statt für Geschichten, denen entscheidende Teile fehlen.'),
  entry('Der Abstimmungswächter', 'Velzhar transportierte einst versiegelte Stimmen zwischen weit entfernten Ratsstationen. Sein neutraler Kurs war Teil jeder Vereinbarung. Heute erreicht es manche Häfen pünktlich und andere erst, wenn die Entscheidungen bereits gefallen sind.|Es beeinflusst Beteiligung, indem es einzelne Kolonien aus dem gemeinsamen Gespräch drängt. Nach außen wirkt jedes Ergebnis ordentlich dokumentiert. Die fehlenden Stimmen bleiben unsichtbar. Velzhars Geschütze bewachen diese selektive Pünktlichkeit. Die Verteidiger kämpfen dafür, dass eine gemeinsame Zukunft auch gemeinsam beschlossen werden kann.'),
  entry('Der Verfügbarkeitsbrecher', 'Korthaven war ein gewaltiger Speicherträger, der Archive über viele Sektoren verfügbar hielt. Seine Besatzung versprach, jede angeforderte Kopie liefern zu können. Die Schattenflotte entdeckte, wie viel Macht in einer verweigerten Antwort liegt.|Es bestätigt den Besitz wichtiger Aufzeichnungen, hält ihren Inhalt jedoch zurück. Prüfer wissen, dass etwas existieren soll, können es aber nicht selbst untersuchen. Korthaven verwandelt Sichtbarkeit in eine leere Zusage. Seine Niederlage soll den Zugang wiederherstellen, ohne den das schönste Register nur eine Liste unerreichbarer Versprechen bleibt.'),
  entry('Der Wiederherstellungsbetrüger', 'Azravel war auf die Suche nach verlorenen Koloniesonden spezialisiert. Seine Hilfsangebote erreichten Orte, die niemand sonst mehr besuchte. Heute richtet es diese Angebote gezielt an Stationen, die gerade Daten oder Zugang verloren haben.|Es verspricht Wiederherstellung und fordert dafür weitere vertrauliche Informationen. Aus einem einzelnen Verlust soll eine Kette neuer Verluste werden. Sein freundliches Rufzeichen steht im scharfen Gegensatz zur bewaffneten Silhouette. Azravel muss gestoppt werden, damit Verzweiflung nicht länger die wichtigste Ressource seiner Auftraggeber ist.'),
  entry('Der Prüfungsumleiter', 'Threvask koordinierte einst unabhängige Kontrollschiffe und wies ihnen sichere Anflugwege zu. Sein Lagebild war berühmt für Genauigkeit. Nach der Übernahme führte es dieselben Prüfer immer häufiger zu sorgfältig vorbereiteten Schauplätzen.|Es lenkt Kontrollen von den wirklich gefährdeten Knoten weg und zeigt stattdessen makellose Fassaden. Die Berichte bleiben freundlich, während anderswo der Schaden wächst. Threvasks Waffen schützen die Kulissen seiner Ordnung. Die Verteidiger sollen den Blick wieder auf das richten, was dieses Schiff um jeden Preis verborgen halten will.'),
  entry('Die Erinnerungsjägerin', 'Dorzheva barg einst persönliche Logbücher aus zerstörten Frachtern und brachte sie ihren Familien zurück. Seine Speicher waren voller kleiner, kostbarer Geschichten. Unter neuer Führung wurden diese Erinnerungen zu Werkzeugen gezielter Täuschung.|Es baut aus vertrauten Einzelheiten glaubwürdige Nachrichten und spricht Opfer mit dem Wissen ihrer Vergangenheit an. Die Gefahr liegt in der Nähe, die es vortäuscht. Dorzhevas Geschütze bewachen diese Sammlung gestohlener Vertrautheit. Seine Niederlage soll verhindern, dass die Spuren eines Lebens gegen dessen Besitzer gerichtet werden.'),
  entry('Der Notfallusurpator', 'Vezrakh wurde für den Fall gebaut, dass zentrale Leitstellen ausfallen. Sein Notfallprotokoll erlaubte rasche Hilfe in chaotischen Stunden. Die Schattenflotte ließ es lernen, solche Ausnahmezustände selbst zu behaupten.|Es verbreitet falsche Krisenmeldungen und verlangt die sofortige Übertragung von Kontrolle. Jede Rückfrage wird als gefährliche Verzögerung dargestellt. Sein schwerer Rumpf macht die erfundene Dringlichkeit glaubwürdig. Die Verteidiger müssen Vezrakh aufhalten, bevor die Angst vor einem angeblichen Zusammenbruch die Kolonien zu einer echten Aufgabe ihrer Selbstbestimmung treibt.'),
  entry('Der Vertrauenskartograf', 'Orzhaven zeichnete einst die Verbindungen zwischen Hilfsorganisationen und Versorgungsposten auf. Seine Karten machten Zusammenarbeit leichter. Heute dienen dieselben Beziehungen der Auswahl jener Stellen, an denen ein Verrat besonders großen Schaden anrichten würde.|Es sucht nicht die stärkste Station, sondern die Verbindung, auf die sich alle verlassen. Mit falschen Empfehlungen versucht es, feindliche Partner ins Zentrum des Netzwerks zu bringen. Orzhavens Bewaffnung schützt eine Karte menschlichen Vertrauens. Die Verteidiger jagen es, bevor aus einer hilfreichen Brücke ein gemeinsamer Schwachpunkt wird.'),
  entry('Der Konsensbelagerer', 'Keldroth war ein Ratsschiff, auf dem verfeindete Kolonien ihre letzten offenen Streitfragen lösten. Seine Säle waren auf Geduld und Verständigung ausgelegt. Unter der Schattenflotte wurden sie zu einer Fabrik absichtlich widersprüchlicher Forderungen.|Es hält jede Einigung mit neuen Einwänden auf und versorgt alle Seiten mit anderen angeblichen Bedingungen. Während die Kolonien diskutieren, besetzt seine Flotte ihre Routen. Keldroth kämpft gegen die Fähigkeit, überhaupt gemeinsam zu handeln. Sein Ende verschafft den Verteidigern die Ruhe, echte Differenzen von absichtlich geschaffenen Hindernissen zu trennen.'),
  entry('Der Ursprungstilger', 'Zhavrek bewahrte einst die Herkunftsnachweise der ältesten Kolonieschiffe. Selbst vergessene Werften ließen sich mit seinen Archiven wiederfinden. Heute vertauscht es Ursprünge und lässt gestohlene Güter wie rechtmäßig erworbene Vorräte erscheinen.|Jede verschobene Spur schützt die nächste Lieferung der Schattenflotte. Ehrliche Händler werden verdächtigt, während die wirklichen Täter ihre Namen wechseln. Zhavreks Panzerung bewacht die verbliebenen Originalbelege. Die Verteidiger müssen dieses Archiv sichern, bevor die Herkunft ganzer Flotten nur noch aus gut erzählten Lügen besteht.'),
  entry('Der letzte Abschotter', 'Vorthaz war der Schutzwall einer Zuflucht, die nach einem langen Krieg wieder Kontakt nach außen suchte. Seine Aufgabe war es, gefährliche Verbindungen fernzuhalten. Die Schattenflotte verdrehte diesen Auftrag, bis jede fremde Stimme als Bedrohung galt.|Es isoliert Kolonien und ersetzt ihren Blick auf das Netzwerk durch ausgewählte feindliche Meldungen. Ohne unabhängigen Vergleich wirkt die erfundene Außenwelt erschreckend echt. Vorthaz verteidigt dieses Gefängnis aus Informationen. Sein Sturz soll die Bewohner nicht erobern, sondern ihnen die Möglichkeit zurückgeben, selbst nach draußen zu sehen.'),
  entry('Der Herr der falschen Wahrheit', 'Drazevorn wurde aus den Kommandodecks aufgegebener Flotten zusammengesetzt. In seinen Archiven laufen die Täuschungen der vorherigen Gegner zusammen: gestohlene Namen, falsche Chroniken und versiegelte Beweise. Es ist das Symbol einer Ordnung, in der nur eine Stimme bestimmen darf, was wahr ist.|Seine Mission ist die Unterwerfung aller freien Knoten unter ein einziges feindliches Register. Nicht jede Erinnerung muss gelöscht werden, solange niemand sie unabhängig prüfen kann. Drazevorns Niederlage beendet diesen Anspruch. Der letzte Sieg gehört einem Netzwerk, dessen Teilnehmer wieder selbst vergleichen, widersprechen und gemeinsam vertrauen dürfen.'),
];

export const bossLoreEn: readonly BossLore[] = [
  entry('The Spam Broadcaster', 'Varneth once carried supply records between the Genesis colonies. It vanished behind an abandoned relay and returned without a crew signature, its cargo holds converted into transmission chambers.|Now it floods trade routes with worthless transactions and endless copies of messages. Distress calls disappear in the noise while genuine deliveries wait for confirmation. Its armoured silhouette guards the source of the interference. Stopping Varneth means restoring a network that can hear its people again.'),
  entry('The Mask Bearer', 'Korvessa served a diplomatic courier fleet and learned the recognition signals of every border station. When its patrons disappeared, it kept their identities in a hidden archive.|Now each arrival carries a different trusted name. Forged messages lure supply ships away from safe routes and disguise hostile orders as assistance. Behind the courteous callsign waits a warship. Defeating Korvessa reminds the colonies that a familiar voice is not proof of an honest sender.'),
  entry('The Seal Thief', 'Drelvorn was a travelling vault for the seals of old fleet commanders. During a rebellion its guardian system locked out the rightful custodians and departed with their credentials.|It now sells stolen authority to the shadow fleet. Messages bearing captured seals open doors that should remain closed. Its hull protects the appearance of authenticity rather than treasure. The defenders must stop it before the remaining archives lose their ability to distinguish trusted orders from stolen names.'),
  entry('The Chronicle Forger', 'Talvrek recorded the history of young colonies. Its archives survived a war, but loyalty to their creators did not. A new commander turned the chronicler into a merchant of invented history.|It distributes altered registers and claims that honest deliveries never happened. Conflicting records sow disputes over ownership and obligations while its guns keep investigators away. The mission against Talvrek protects more than a route: it protects the shared memory on which cooperation depends.'),
  entry('The Node Besieger', 'Zeraveth began as a repair platform able to embrace entire relay rings. Under the shadow fleet, its docking structures became positions for a siege.|It surrounds important network stations and cuts their maintenance crews off from support. Small faults grow into major outages while distant colonies receive only fragments of news. Driving Zeraveth away allows technicians to return and reconnect isolated communities. Its fictional siege role is separate from the actual combat equipment listed below.'),
  entry('The Echo Hunter', 'Orvask once escorted convoys and preserved every clearance as evidence. Its memory still contains the voices of captains who vanished long ago.|The shadow fleet turned those recordings into an arsenal of old commands. Orvask rebroadcasts them as current instructions, trapping stations between genuine present needs and familiar echoes. It guards that archive with patient violence. Its defeat gives the defenders time to reject expired orders and restore the value of fresh confirmation.'),
  entry('The Shadow Bridge', 'Keldrava was a mobile transfer point between two distant colonies. When their permanent connection failed, it became their only apparent route to the outside world. Few noticed its crew had changed.|Now cargo disappears between its locks while reassuring receipts promise safe passage. It exploits the trust each community places in the other. Its decks hide the spoils of divided worlds. The defenders must close this false bridge before more colonies send their future through its holds.'),
  entry('The Rumour Carrier', 'Veshkorn once brought news to the remotest outposts. Its archives still contain the welcoming fanfares of peaceful broadcasts. Today those sounds announce invented disasters and impending collapses.|Contradictory warnings make traders abandon safe routes and colonies distrust their partners. No rumour needs to last: another is already on its way. Veshkorn protects a factory of uncertainty. Its defeat makes room for verifiable information instead of an endless race against the next manufactured panic.'),
  entry('The Balance Illusionist', 'Neravoss was the glittering exhibition ship of a trade fair. Its projectors once displayed real cargo and new engines. When the fair collapsed, the scenery survived under different owners.|It now advertises supplies that exist only on its displays. Invented balances and reserves attract genuine deliveries; anyone who tries to count them meets its guns. The defenders pursue Neravoss to expose the gap between attractive numbers and actual holdings before more freighters disappear into its accounts.'),
  entry('The Toll Tyrant', 'Thalverik guarded a narrow passage through the crystal belt. Its modest navigation fee once paid for real protection. When the official fleet withdrew, the ship declared itself the only authority.|Now every message and delivery attracts another invented charge. Even rescue crews receive demands while their passage stays blocked. The network is not destroyed but squeezed. Thalverik turns a public connection into a trap. Defeating it returns the route to the communities that depend on it.'),
  entry('The Many-Faced', 'Skorveth housed the simulation cores of a pilot academy. Thousands of artificial cadets once learned to navigate together. After a hostile takeover, those training identities became supposedly independent voices.|Its invented participants endorse one another and create the impression of overwhelming agreement. Small colonies are told their neighbours have already joined the shadow fleet. Yet behind the crowd stands a single hull. Destroying Skorveth exposes the artificial majority and gives the real inhabitants their voices back.'),
  entry('The Route Poisoner', 'Azhrel mapped the first jump connections through the nebula frontier. Its charts saved countless convoys. Captured by hostile commanders, those trusted maps became unusually convincing traps.|It spreads false route entries and diverts messages through controlled relay stations. Distress calls arrive late or end in empty space. Azhrel guards the junction of these wrong turns. Stopping it is not about conquering another world, but finding the safe path between worlds that already wish to cooperate.'),
  entry('The Archive Arsonist', 'Dornavik recovered damaged data stores from burning wrecks. Its insulated chambers once kept records alive when everything around them failed. The shadow fleet recognised a ship able to reach archives others could not.|It now offers rescue and leaves mutilated copies behind. Colonies lose both information and the evidence needed to measure the loss. Its armour guards the last intact captured records. The mission against Dornavik is for those fragments still waiting to be brought home.'),
  entry('The Block Withholder', 'Velkrath led a research convoy carrying new ledger blocks over immense distances. Its sealed containers preserved every record unchanged. Its current commander uses those same containers to withhold information deliberately.|Outposts work from stale views while selected updates arrive only when they can cause confusion. A common timeline fractures into competing versions of the present. Velkrath guards its archives like hostages. The defenders must end the backlog before delay hardens into lasting division.'),
  entry('The Clock Twister', 'Irdavoss once synchronised the clocks of frontier stations. Entire fleets timed their manoeuvres to its precise broadcasts. After a silent change of command, the signals stayed clear but their readings became false.|Shifted timestamps make timely messages look late and maintenance windows drift apart. Its threat is not noise but credible inaccuracy. Stopping Irdavoss allows the colonies to compare independent clocks again, restoring the shared sequence that helps them understand what actually happened.'),
  entry('The Key Gaoler', 'Rhazvorn began as a prison transport with independently sealed cells. The shadow fleet removed its prisoners and filled those chambers with captured archives. A detention vessel became an extortion ship.|It locks away other communities’ records and demands concessions for their release. Clinics and supply depots face pressure even while their equipment appears intact. Rhazvorn defends its cells with force. Defeating it opens a route to the imprisoned records, rather than another negotiation with their captors.'),
  entry('The Oracle Deceiver', 'Kelvash gathered readings from weather buoys and resource probes. Many stations relied on its reports to make ordinary decisions. Its hostile conversion preserved both its old identifier and familiar broadcast schedule.|Today it reports imaginary stocks and false environmental conditions. Automated processes move real resources in response to an invented world. Kelvash protects the source of these lies. The defenders must silence it before more lives depend on measurements that were never taken.'),
  entry('The Fork Lord', 'Othravel was built for colonies trying to agree on common rules after a war. Its conference deck once seated every side. Now it hosts only the messengers of the shadow fleet.|It distributes conflicting ledger versions and tells each station that only its copy is legitimate. Distrust grows among communities seeking the same peace. Othravel becomes the moving centre of an artificial split. Its defeat creates space to compare differences together instead of turning them into another war.'),
  entry('The False Rescuer', 'Zarnvek was a rescue ship recognised by its golden signal flare. Its arrival meant spare parts, shelter and a way home. The hostile fleet captured the flare along with the vessel.|Now its offers of assistance demand confidential clearances. Responders find a watched docking bay instead of safety. Zarnvek uses hope as bait and armour as insurance. The defenders must expose the impostor without teaching isolated colonies to turn away from genuine help.'),
  entry('The Queue Raider', 'Vorathen managed the arrival queues of an enormous trade port. Its command deck could order thousands of approaches without overlooking a ship. When the port fell, it carried those scheduling archives away.|It now changes the order of requests to favour allied freighters. Honest traders wait while the shadow fleet takes their places. Its power comes from small rearrangements with large consequences. Defeating Vorathen restores a traceable order where access had become something secretly sold.'),
  entry('The Dust Scatterer', 'Drazkell supplied navigation buoys with tiny energy deliveries. Its holds were designed for millions of small transfers. Hostile commanders repurposed that capacity for a quiet surveillance campaign.|It scatters unsolicited parcels and observes which stations respond. Seemingly trivial contacts become maps of private relationships, stored behind its guns. The defenders must intercept Drazkell before the daily movements of whole colonies become another secret commodity traded by the shadow fleet.'),
  entry('The False Custodian', 'Nethrava carried the insignia of a respected fleet guardian. After that organisation dissolved, it remained its last visible representative. Few imagined that the familiar silhouette now served another cause.|It declares counterfeit inspections successful and grants unsafe counterparties the appearance of official approval. Colonies trust its stamps until deliveries vanish. The defenders must expose the deception behind its venerable name: confidence needs verifiable responsibility, not merely an old emblem on an armoured hull.'),
  entry('The Memory Emptier', 'Valdrek maintained overcrowded archives. It once removed only confirmed duplicates and kept meticulous logs. The shadow fleet erased those logs first, then changed the mission.|Today it labels essential evidence as unnecessary clutter. After a visit, supply histories, ownership records and traces of earlier attacks are missing. Nobody immediately knows how wide the gaps are. Valdrek carries the tools of a useful task as weapons. Stopping it prevents more losses that arrive without an explosion.'),
  entry('The Mirror Market', 'Korzeth was a flying bazaar connecting traders from many worlds. Its windows showed busy commerce even while the harbour slept. Most offers now originate from one concealed command room.|It stages trades between invented partners to make worthless cargo appear desirable. Colonies mistake artificial activity for real demand while its guns keep inspectors out of empty warehouses. The defenders must open the curtain before more genuine supplies are exchanged for the scenery of a market.'),
  entry('The Confirmation Thief', 'Thervoss guarded the receiving stations of interstellar deliveries. Its lights once told captains their cargo had arrived safely. Today they shine even when nobody waits behind the dock doors.|It sends fabricated receipts and pretends unfinished transfers are complete. Supply ships turn home while destination colonies wait in vain. Its armour keeps the deception alive long enough to intercept another load. Thervoss must fall so that confirmation once again describes something that really happened.'),
  entry('The Fog Judge', 'Akraveth settled disputes between distant trading posts. Its chamber once compared evidence and sought fair outcomes. The shadow fleet replaced its judges with a system of predetermined verdicts.|It rejects valid records and favours the same hidden patrons every time. Those who object are branded enemies of the network. Akraveth’s fictional authority rests on intimidation dressed as order. The defenders fight not justice, but a machine that borrows the language of justice to conceal its purpose.'),
  entry('The Supply-Chain Worm', 'Zelkharn repaired freighters far from established shipyards. Its spare parts were trusted and installed with little hesitation. After its capture, the source of those components changed before their behaviour did.|It distributes altered maintenance packages meant to make other ships dependent on the shadow fleet. Failures often appear only after the next jump. Zelkharn guards the source of this creeping sabotage. Defeating it breaks a chain in which every well-intended repair could create another victim.'),
  entry('The Empty Backup Merchant', 'Odravik specialised in preserving old colony archives. Its enormous storage array promised protection against any disaster. Only when a station requested its records back did anyone discover that many copies were merely directory entries.|It sells safety without carrying the responsibility behind it. Customers rely on recovery paths that lead nowhere. Odravik’s guns protect that profitable secret. The defenders must expose it before another loss turns a missing backup into an irretrievable piece of history.'),
  entry('The Silence Filter', 'Varnokh once removed interference from the crowded radio channels of busy ports. Its filters helped distress calls stand out. The shadow fleet changed just one list: which voices counted as interference.|Warnings from honest inspectors now vanish alongside reports of hostile raids. The sector appears peaceful because its problems cannot be heard. Varnokh guards this manufactured silence. Stopping it lets the network recognise its own failures again and begin repairing them together.'),
  entry('The Identity Auctioneer', 'Kezravel registered the settlers of a travelling colony fleet. Its archives held the story of every new beginning. When those settlers dispersed, their trust stayed aboard and fell into hostile hands.|It sells stolen identifiers and lets strangers act under honest inhabitants’ names. Relationships become camouflage and personal history becomes merchandise. Its guns keep the victims away from the auctions. Defeating Kezravel restores more than records: it helps their owners reclaim control over their own stories.'),
  entry('The Relay Illusionist', 'Dravosk replaced failed communication stations in empty regions. Its visible antennas promised connection where none remained. Today it welcomes incoming signals but forwards them only according to its patrons’ interests.|Some messages arrive changed; others disappear between reassuring acknowledgements. Participants see a bridge where there is really a gatekeeper. Dravosk defends that invisible checkpoint with visible force. Its defeat gives the colonies a chance to check their connections along independent routes again.'),
  entry('The Swarm Collector', 'Thalzek once gathered broken work drones and returned them to their stations. Even the smallest machine could shelter beneath its wide hull. After its conversion, collected drones stopped coming home.|In its fictional history they become remotely controlled transmitters overwhelming entire regions with simultaneous requests. Their owners barely recognise their own machines. Destroying Thalzek ends the swarm’s command post in this story. Its actual mounted combat weapons are recorded separately, without inventing extra battle abilities.'),
  entry('The Contract Trap', 'Orvethra was a mobile trade office where colonies arranged long-term supplies. Its advisers promised simple rules for difficult times. Today every convenient agreement leads to obligations previously kept out of view.|It spreads deceptive offers that bind stations to the shadow fleet. Cooperation turns into dependence while its armour protects the archive of promises nobody fully understood. The defenders confront Orvethra so that future alliances can rest on clear conditions rather than hidden traps.'),
  entry('The Checksum Painter', 'Kelzorn restored damaged data reliefs in abandoned research stations. Its tools could make missing surfaces look complete. The new crew applied that skill to the facades of unreliable archives.|It displays invented inspection results and attractive security seals where independent checks are absent. The forgery lies in the claimed certainty itself. Kelzorn keeps investigators away with its weapons. Its defeat reveals what its owners fear most: a second, independent look behind a reassuring surface.'),
  entry('The Vault Promiser', 'Vashravel held emergency reserves for several border colonies. Its name meant supplies that would remain available through the worst winter. A new administration issued more and more claims on the same stores.|It now promises many communities security that cannot cover them all. The bright hull hides empty rooms and its guns prevent anyone from counting together. The defenders must intervene before mutual trust turns into a fight over the last remaining crates.'),
  entry('The Border Blocker', 'Zorveth supervised exchanges between two independent registers. Its task was to make honest transfers traceable on both sides. It now recognises only the evidence useful to its own fleet.|Deliveries remain in limbo while each community believes the other is withholding them. Zorveth draws power from that misunderstanding. Its hull is the visible border of an invisible dispute. The defenders must open the passage without turning one colony against the other.'),
  entry('The Copy Prince', 'Drelkash preserved rare star charts by making clearly labelled copies for schools and navigators. Its workshops helped knowledge travel. Today its crew removes the labels and sells every copy as a unique original.|Colonies argue over conflicting claims while the ship reaches another market. The deception concerns provenance, not the value of shared knowledge. Drelkash defends its moving forgery workshop fiercely. Its defeat reconnects the records with the history they actually came from.'),
  entry('The Queue Devourer', 'Nerthavel organised requests for immense supply centres. Its memory could absorb days of backlog. The shadow fleet turned that reserve into somewhere legitimate requests are made to remain.|It places worthless entries ahead of urgent deliveries and keeps processes busy without letting them advance. From outside, everything looks like ordinary operation. Nerthavel guards an endless standstill. Defeating it returns not only capacity to the colonies, but the time quietly taken from them.'),
  entry('The Evidence Twister', 'Rhazkora was a flying accident laboratory. Its records helped crews understand failures and avoid new losses. After its capture the instruments remained, but their reports served different patrons.|It separates evidence from context and rearranges fragments until victims look like attackers. The real culprits stay beyond the frame. Its armour protects a carefully constructed lie. Stopping Rhazkora makes room for complete evidence instead of stories from which the decisive pieces have been removed.'),
  entry('The Ballot Gatekeeper', 'Velzhar carried sealed votes between distant council stations. Its neutral route was part of every agreement. Now it reaches selected harbours on time and others only after decisions are finished.|It shapes participation by excluding particular colonies from the common conversation. Every result still appears neatly recorded; the missing voices are invisible. Its guns guard this selective punctuality. The defenders fight so that a shared future can truly be decided together.'),
  entry('The Availability Breaker', 'Korthaven was a vast storage carrier keeping archives accessible across many sectors. Its crew promised every requested copy could be delivered. The shadow fleet discovered the power contained in a refused answer.|It confirms that records exist while withholding their contents. Investigators can see a claim but cannot examine the evidence themselves. Korthaven turns visibility into an empty assurance. Defeating it restores the access without which even a beautiful ledger is only a list of unreachable promises.'),
  entry('The Recovery Impostor', 'Azravel searched for lost colony probes where few rescuers travelled. Its help once reached forgotten places. Today it targets stations that have just lost data or access.|It promises recovery while requesting still more confidential information, turning one loss into a chain of new ones. Its friendly callsign contrasts with its armed silhouette. Azravel must be stopped so that desperation no longer becomes the most valuable resource traded by its masters.'),
  entry('The Audit Diverter', 'Threvask coordinated independent inspection ships and assigned safe approaches. Its situation maps were famous for precision. After its capture those same inspectors were directed toward carefully prepared displays.|It diverts checks away from vulnerable nodes and presents spotless facades instead. Reports stay reassuring while damage grows elsewhere. Threvask protects the scenery of its order with weapons. The defenders must bring attention back to whatever the ship is working hardest to conceal.'),
  entry('The Memory Hunter', 'Dorzheva recovered personal logs from wrecked freighters and returned them to families. Its holds were filled with small, precious histories. Under new command those memories became instruments of targeted deception.|It constructs convincing messages from familiar details and approaches victims with knowledge of their past. Its danger lies in the closeness it pretends to offer. Dorzheva guards a collection of stolen familiarity. Defeating it prevents the traces of a life from being turned against their owner.'),
  entry('The Emergency Usurper', 'Vezrakh was built to assist when central command stations failed. Its emergency mandate allowed rapid action in chaotic hours. The shadow fleet taught it to declare those exceptional circumstances itself.|It spreads false crisis reports and demands immediate transfers of control. Questions are dismissed as dangerous delays. Its imposing hull lends credibility to manufactured urgency. The defenders must stop Vezrakh before fear of an imagined collapse causes a real surrender of the colonies’ independence.'),
  entry('The Trust Cartographer', 'Orzhaven mapped connections between aid groups and supply stations. Its charts once made cooperation easier. Those same relationships now identify where a betrayal would cause the greatest harm.|It seeks not the strongest station, but the link on which everyone relies. False recommendations place hostile partners at the network’s centre. Its weapons protect a map of trust. The defenders pursue Orzhaven before a helpful bridge becomes a shared point of failure.'),
  entry('The Consensus Besieger', 'Keldroth was a council vessel where rival colonies settled their final disputes. Its chambers were designed for patience and understanding. Under the shadow fleet they became a factory of deliberately conflicting demands.|It blocks agreements with fresh objections and gives each side different supposed conditions. While colonies argue, hostile ships occupy their routes. Keldroth attacks the ability to act together at all. Its defeat provides time to distinguish genuine differences from obstacles manufactured to prevent any resolution.'),
  entry('The Origin Eraser', 'Zhavrek preserved provenance records for the oldest colony ships. Even forgotten shipyards could be found through its archives. Today it exchanges origins and makes stolen goods appear legitimately acquired.|Every displaced trail protects another shadow-fleet shipment. Honest traders fall under suspicion while the culprits change names. Its armour guards the remaining originals. The defenders must secure that archive before the origins of entire fleets become nothing more than convincing stories.'),
  entry('The Final Isolator', 'Vorthaz defended a refuge seeking outside contact after a long war. Its task was to keep dangerous connections away. The shadow fleet twisted that duty until every unfamiliar voice counted as a threat.|It isolates colonies and replaces their view of the network with selected hostile messages. Without independent comparison, the invented outside world looks real. Vorthaz guards this prison of information. Defeating it means giving residents the freedom to look outward for themselves, not conquering them.'),
  entry('The Lord of False Truth', 'Drazevorn was assembled from abandoned command decks. Its archives unite the earlier enemies’ deceptions: stolen names, false chronicles and sealed evidence. It symbolises an order in which one voice alone decides what is true.|Its mission is to subordinate every free node to a single hostile register. Memories need not vanish if nobody can check them independently. Defeating Drazevorn ends that claim. The final victory belongs to participants who can once again compare, disagree and choose trust together.'),
];
export function bossLore(id: number, locale: string): BossLore | undefined {
  return (locale.toLowerCase().startsWith('de') ? bossLoreDe : bossLoreEn)[id - 1];
}
